15	static FormatSettings updateFormatSettings(const FormatSettings & settings)
16	{
17	    if (settings.custom.escaping_rule != FormatSettings::EscapingRule::CSV || settings.custom.field_delimiter.empty())
18	        return settings;
19	
20	    auto updated = settings;
21	    updated.csv.delimiter = settings.custom.field_delimiter.front();
22	    return updated;
23	}
