38	CustomSeparatedRowInputFormat::CustomSeparatedRowInputFormat(
39	    const Block & header_,
40	    std::unique_ptr<PeekableReadBuffer> buf_,
41	    const Params & params_,
42	    bool with_names_,
43	    bool with_types_,
44	    bool ignore_spaces_,
45	    const FormatSettings & format_settings_)
46	    : RowInputFormatWithNamesAndTypes(
47	        header_,
48	        *buf_,
49	        params_,
50	        false,
51	        with_names_,
52	        with_types_,
53	        format_settings_,
54	        std::make_unique<CustomSeparatedFormatReader>(*buf_, ignore_spaces_, format_settings_))
55	    , buf(std::move(buf_))
56	{
57	    /// In case of CustomSeparatedWithNames(AndTypes) formats and enabled setting input_format_with_names_use_header we don't know
58	    /// the exact number of columns in data (because it can contain unknown columns). So, if field_delimiter and row_after_delimiter are
59	    /// the same and row_between_delimiter is empty, we won't be able to determine the end of row while reading column names or types.
60	    if ((with_types_ || with_names_) && format_settings_.with_names_use_header
61	        && format_settings_.custom.field_delimiter == format_settings_.custom.row_after_delimiter
62	        && format_settings_.custom.row_between_delimiter.empty())
63	    {
64	        throw Exception(ErrorCodes::BAD_ARGUMENTS,
65	                        "Input format CustomSeparatedWithNames(AndTypes) cannot work properly with enabled setting input_format_with_names_use_header, "
66	                        "when format_custom_field_delimiter and format_custom_row_after_delimiter are the same and format_custom_row_between_delimiter is empty.");
67	    }
68	}
