139	bool CustomSeparatedFormatReader::checkEndOfRow()
140	{
141	    PeekableReadBufferCheckpoint checkpoint{*buf, true};
142	
143	    skipSpaces();
144	    if (!checkString(format_settings.custom.row_after_delimiter, *buf))
145	        return false;
146	
147	    skipSpaces();
148	
149	    /// At the end of row after row_after_delimiter we expect result_after_delimiter or row_between_delimiter.
150	
151	    if (checkString(format_settings.custom.row_between_delimiter, *buf))
152	        return true;
153	
154	    buf->rollbackToCheckpoint();
155	    skipSpaces();
156	    buf->ignore(format_settings.custom.row_after_delimiter.size());
157	    return checkForSuffixImpl(true);
158	}
