160	template <bool is_header>
161	String CustomSeparatedFormatReader::readFieldIntoString(bool is_first)
162	{
163	    if (!is_first)
164	        skipFieldDelimiter();
165	    skipSpaces();
166	    if constexpr (is_header)
167	        return readStringByEscapingRule(*buf, format_settings.custom.escaping_rule, format_settings);
168	    else
169	        return readFieldByEscapingRule(*buf, format_settings.custom.escaping_rule, format_settings);
170	}
