196	void CustomSeparatedFormatReader::skipHeaderRow()
197	{
198	    skipRowStartDelimiter();
199	    bool first = true;
200	    do
201	    {
202	        if (!first)
203	            skipFieldDelimiter();
204	        first = false;
205	
206	        skipField();
207	    }
208	    while (!checkEndOfRow());
209	
210	    skipRowEndDelimiter();
