219	bool CustomSeparatedFormatReader::checkForSuffixImpl(bool check_eof)
220	{
221	    skipSpaces();
222	    if (format_settings.custom.result_after_delimiter.empty())
223	    {
224	        if (!check_eof)
225	            return false;
226	
227	        return buf->eof();
228	    }
229	
230	    if (unlikely(checkString(format_settings.custom.result_after_delimiter, *buf)))
231	    {
232	        skipSpaces();
233	        if (!check_eof)
234	            return true;
235	
236	        if (buf->eof())
237	            return true;
238	    }
239	    return false;
240	}
