306	DataTypes CustomSeparatedSchemaReader::readRowAndGetDataTypes()
307	{
308	    if (reader.checkForSuffix())
309	        return {};
310	
311	    if (!first_row || with_names || with_types)
312	        reader.skipRowBetweenDelimiter();
313	
314	    if (first_row)
315	        first_row = false;
316	
317	    auto fields = reader.readRow();
318	    return determineDataTypesByEscapingRule(fields, reader.getFormatSettings(), reader.getEscapingRule());
