321	void registerInputFormatCustomSeparated(FormatFactory & factory)
322	{
323	    for (bool ignore_spaces : {false, true})
324	    {
325	        auto register_func = [&](const String & format_name, bool with_names, bool with_types)
326	        {
327	            factory.registerInputFormat(format_name, [=](
328	                ReadBuffer & buf,
329	                const Block & sample,
330	                IRowInputFormat::Params params,
331	                const FormatSettings & settings)
332	            {
333	                return std::make_shared<CustomSeparatedRowInputFormat>(sample, buf, params, with_names, with_types, ignore_spaces, settings);
334	            });
335	        };
336	        registerWithNamesAndTypes(ignore_spaces ? "CustomSeparatedIgnoreSpaces" : "CustomSeparated", register_func);
337	        markFormatWithNamesAndTypesSupportsSamplingColumns(ignore_spaces ? "CustomSeparatedIgnoreSpaces" : "CustomSeparated", factory);
338	    }
339	}
